namespace Wpf.Zen.Ui.Controls;

/// <summary>
/// Represents a read-only page item generated by a paging control.
/// </summary>
public sealed class PagingItem(
    int page,
    PagingItemState state,
    bool isCurrent,
    bool isEnabled,
    string description)
{
    /// <summary>Gets the page number.</summary>
    public int Page { get; } = page;

    /// <summary>Gets the display state of the page item.</summary>
    public PagingItemState State { get; } = state;

    /// <summary>Gets a value indicating whether the item represents the current page.</summary>
    public bool IsCurrent { get; } = isCurrent;

    /// <summary>Gets a value indicating whether the user can currently request this page.</summary>
    public bool IsEnabled { get; } = isEnabled;

    /// <summary>Gets a value indicating whether the item is an ellipsis navigation item.</summary>
    public bool IsEllipsis => State is PagingItemState.PreviousEllipsis or PagingItemState.NextEllipsis;

    /// <summary>Gets the localized page-item description used by tooltips and accessibility clients.</summary>
    public string Description { get; } = description;
}
